sys_ws_operation.operation_script:
(function process(request, response) {

    var userSysId = request.queryParams.user_sys_id;
    var date = request.queryParams.date;

    // Validate mandatory parameters
    if (!userSysId || !date) {
        response.setStatus(400);
        response.setBody({
            result: {
                success: false,
                message: "user_sys_id and date are required"
            }
        });
        return;
    }

    // Validate date format
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
        response.setStatus(400);
        response.setBody({
            result: {
                success: false,
                message: "Date must be in YYYY-MM-DD format"
            }
        });
        return;
    }

    // Find existing daily timesheet
    var gr = new GlideRecordSecure(
        'x_2131768_timesh_0_timesheet_main'
    );

    gr.addQuery('user', userSysId);
    gr.addQuery('lab_date', date);
    gr.setLimit(1);
    gr.query();

    // If no timesheet exists
    if (!gr.next()) {
        response.setStatus(404);
        response.setBody({
            result: {
                success: false,
                message: "Daily timesheet not found"
            }
        });
        return;
    }

    // Prepare response
    response.setStatus(200);
    response.setBody({
        result: {
            success: true,
            data: {
                timesheet_sys_id: gr.getUniqueValue(),
                number: gr.getValue('number'),
                user_sys_id: gr.getValue('user'),
                date: gr.getValue('lab_date'),
                approved: gr.getValue('approved')
            }
        }
    });

})(request, response);
